settings.custom_css:
/* ===== Venus service page ===== */
body{background-color:#FFFBE9}
html,body{overflow-x:clip!important;overflow-y:visible!important}
selector{width:calc(100% - 8vw);max-width:1240px;margin:0 auto;padding:24px 0 96px;gap:0;display:block;font-family:var(--e-global-typography-vnsbody-font-family),"Discovery Fs",system-ui,sans-serif;font-size:18px;font-weight:300;line-height:1.3;color:#141414}
selector .elementor-widget{margin:0}
selector a{text-decoration:none}
selector .vsv-crumbs{display:flex;flex-wrap:wrap;gap:8px;font-size:15px;color:rgba(20,20,20,.6)}
selector .vsv-crumbs a{color:inherit}
selector .vsv-crumbs a:hover{color:var(--e-global-color-vnsgreen,#3A4831);text-decoration:underline}
selector .vsv-crumbs i{font-style:normal;opacity:.5}
selector .vsv-crumbs span{color:#141414}
selector .vsv-h2{margin:0;font-family:"Leon","Discovery Fs",system-ui,sans-serif;font-weight:700;font-size:44px;line-height:1.1;color:#141414}
selector .vsv-p{margin:14px 0 0;font-size:19px;line-height:1.65;color:rgba(20,20,20,.78)}
selector .vsv-split{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:56px;align-items:center}
selector .vsv-sec{margin-top:110px}
selector .vsv-btn{box-sizing:border-box;display:inline-flex;align-items:center;justify-content:center;gap:8px;height:52px;padding:0 28px;border-radius:12px;font-size:17px;font-weight:500;line-height:1;white-space:nowrap;transition:background .15s,color .15s,border-color .15s}
selector .vsv-btn svg{width:20px;height:20px;flex:none}
selector .vsv-btn-green{background:var(--e-global-color-vnsgreen,#3A4831);color:#fff}
selector .vsv-btn-green:hover{background:#2C3624;color:#fff}
selector .vsv-btn-line{border:1px solid #141414;color:#141414}
selector .vsv-btn-line:hover{background:var(--e-global-color-vnsgreen,#3A4831);border-color:var(--e-global-color-vnsgreen,#3A4831);color:#fff}
selector .vsv-btn-cream{background:#FFFBE9;color:var(--e-global-color-vnsgreen,#3A4831)}
selector .vsv-btn-cream:hover{background:#fff;color:var(--e-global-color-vnsgreen,#3A4831)}
selector .vsv-btns{display:flex;flex-wrap:wrap;gap:12px;margin-top:30px}
selector .vsv-img img{display:block;width:100%;height:auto;object-fit:cover;border-radius:16px}
/* hero */
selector .vsv-hero{margin-top:20px}
selector .vsv-title{margin:22px 0 0;font-family:"Leon","Discovery Fs",system-ui,sans-serif;font-weight:700;font-size:62px;line-height:1.05;color:#141414}
selector .vsv-title b{font-weight:inherit;color:var(--e-global-color-vnsgreen,#3A4831)}
selector .vsv-trust{display:flex;flex-wrap:wrap;gap:8px 18px;margin-top:26px;font-size:15px;color:rgba(20,20,20,.65)}
selector .vsv-trust span{display:inline-flex;align-items:center;gap:6px}
selector .vsv-trust svg{width:18px;height:18px;color:var(--e-global-color-vnsgreen,#3A4831)}
selector .vsv-hero .vsv-img img{aspect-ratio:4/5}
/* numbered list */
selector .vsv-list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}
selector .vsv-item{padding:26px;border:1px solid rgba(20,20,20,.18);border-radius:16px;background:#fff}
selector .vsv-item em{display:block;font-style:normal;font-family:"Leon","Discovery Fs",system-ui,sans-serif;font-size:28px;line-height:1;color:var(--e-global-color-vnsgreen,#3A4831)}
selector .vsv-item h3{margin:14px 0 0;font-family:"Leon","Discovery Fs",system-ui,sans-serif;font-size:22px;font-weight:700;line-height:1.2}
selector .vsv-item p{margin:8px 0 0;font-size:16px;line-height:1.6;color:rgba(20,20,20,.75)}
/* rows list (events / steps / factors) */
selector .vsv-rows{margin-top:26px;border-top:1px solid rgba(20,20,20,.18)}
selector .vsv-row{display:flex;gap:18px;padding:20px 0;border-bottom:1px solid rgba(20,20,20,.18)}
selector .vsv-row em{flex:none;width:34px;font-style:normal;font-family:"Leon","Discovery Fs",system-ui,sans-serif;font-size:22px;line-height:1.3;color:var(--e-global-color-vnsgreen,#3A4831)}
selector .vsv-row em svg{display:block;width:24px;height:24px;margin-top:2px}
selector #quote{display:block;position:relative;top:-24px}
selector .vsv-row h3{margin:0;font-size:20px;font-weight:500;line-height:1.35;color:#141414}
selector .vsv-row p{margin:6px 0 0;font-size:16px;line-height:1.6;color:rgba(20,20,20,.75)}
/* gallery */
selector .vsv-gal-h{display:flex;justify-content:space-between;align-items:flex-end;gap:24px}
selector .vsv-ggrid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));grid-auto-rows:230px;grid-auto-flow:dense;gap:16px;margin-top:36px}
selector .vsv-ggrid figure{position:relative;margin:0;border-radius:12px;overflow:hidden}
selector .vsv-ggrid figure.w2{grid-column:span 2}
selector .vsv-ggrid figure.h2{grid-row:span 2}
selector .vsv-ggrid img{display:block;width:100%;height:100%;object-fit:cover;transition:transform .6s cubic-bezier(.16,1,.3,1)}
selector .vsv-ggrid figure:hover img{transform:scale(1.04)}
selector .vsv-ggrid figcaption{position:absolute;right:12px;bottom:12px;left:12px;padding:8px 12px;border-radius:8px;background:rgba(255,251,233,.92);font-size:14px;font-style:normal;font-weight:500;line-height:1.35;color:#141414}
/* quote */
selector .vsv-quote{align-items:start;--gap:56px;gap:56px;padding:0}
selector .vsv-quote>.e-con{--padding-top:0px;--padding-right:0px;--padding-bottom:0px;--padding-left:0px;min-width:0;width:auto}
selector .vsv-formcard{padding:40px!important;border:1px solid rgba(20,20,20,.18);border-radius:16px;background:#fff;gap:0;--gap:0px;scroll-margin-top:24px}
selector .vsv-formcard .vsv-p{margin-bottom:26px}
selector .vsv-form .elementor-field-group{margin-bottom:16px}
selector .vsv-form .elementor-field-label{margin-bottom:6px;font-size:15px;font-weight:500;color:#141414;font-family:inherit}
selector .vsv-form .elementor-mark-required .elementor-field-label:after{color:var(--e-global-color-vnsgreen,#3A4831)}
selector .vsv-form .elementor-field-textual,selector .vsv-form .elementor-select-wrapper select{box-sizing:border-box;min-height:50px;padding:0 14px;border:1px solid rgba(20,20,20,.18)!important;border-radius:6px!important;background:#fff!important;color:#141414!important;font-family:inherit!important;font-size:17px!important;font-weight:300;line-height:1.3;box-shadow:none!important}
selector .vsv-form textarea.elementor-field-textual{min-height:120px;padding:12px 14px}
selector .vsv-form .elementor-field-textual:focus,selector .vsv-form select:focus{border-color:var(--e-global-color-vnsgreen,#3A4831)!important;outline:none}
selector .vsv-form .elementor-select-wrapper:before,selector .vsv-form .select-caret-down-wrapper{color:#141414!important;font-size:13px}
selector .vsv-form .select-caret-down-wrapper svg{fill:#141414!important;width:12px;height:12px}
selector .vsv-form .elementor-field-type-submit{margin-top:8px;margin-bottom:0}
selector .vsv-form .elementor-button{width:100%;min-height:54px;border-radius:12px!important;background:var(--e-global-color-vnsgreen,#3A4831)!important;color:#fff!important;font-family:inherit!important;font-size:18px!important;font-weight:500!important;transition:background .15s}
selector .vsv-form .elementor-button:hover{background:#2C3624!important}
selector .vsv-form .elementor-message{font-size:16px;margin-top:12px}
selector .vsv-note{margin:14px 0 0;font-size:14px;color:rgba(20,20,20,.55);text-align:center}
selector .vsv-sticky{position:sticky;top:24px}
/* reviews */
selector .vpa-revs{margin-top:110px}
selector .vpa-revs .vpa-h2{margin:0;text-align:center;font-family:"Leon","Discovery Fs",system-ui,sans-serif;font-weight:700;font-size:44px;line-height:1.1;color:#141414}
selector .vpa-sub{margin:10px 0 0;text-align:center;font-size:19px;color:rgba(20,20,20,.72)}
selector .vpa-ti{margin-top:32px;min-height:240px}
selector .vpa-ti .ti-widget,selector .vpa-ti .ti-widget *{font-family:var(--e-global-typography-vnsbody-font-family),"Discovery Fs",system-ui,sans-serif!important}
selector .vpa-ti .ti-widget .ti-inner.ti-inner.ti-inner{background-color:#fff!important}
/* faq */
selector .vsv-faq{align-items:start}
selector .vsv-faq-l{border-top:1px solid rgba(20,20,20,.18)}
selector .vsv-faq-l details{border-bottom:1px solid rgba(20,20,20,.18)}
selector .vsv-faq-l summary{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:20px 4px;cursor:pointer;list-style:none;font-size:20px;font-weight:400;color:#141414;-webkit-tap-highlight-color:transparent}
selector .vsv-faq-l summary::-webkit-details-marker{display:none}
selector .vsv-faq-l summary::after{content:"";flex:none;width:12px;height:12px;border-left:1.5px solid currentColor;border-bottom:1.5px solid currentColor;transform:rotate(-45deg) translateY(-3px);transition:transform .25s}
selector .vsv-faq-l details[open] summary::after{transform:rotate(135deg) translateY(-3px)}
selector .vsv-faq-l summary:hover{color:var(--e-global-color-vnsgreen,#3A4831)}
selector .vsv-faq-l details p{margin:0;padding:0 4px 22px;font-size:17px;line-height:1.65;color:rgba(20,20,20,.8)}
selector .vsv-more{display:inline-block;margin-top:18px;font-size:17px;font-weight:500;color:var(--e-global-color-vnsgreen,#3A4831);text-decoration:underline;text-underline-offset:3px}
/* closing */
selector .vsv-cta{padding:64px 32px;border-radius:16px;background:var(--e-global-color-vnsgreen,#3A4831);color:#FFFBE9;text-align:center}
selector .vsv-cta .vsv-h2{color:#FFFBE9}
selector .vsv-cta .vsv-p{max-width:600px;margin-inline:auto;color:rgba(255,251,233,.85)}
selector .vsv-cta .vsv-btns{justify-content:center}
selector .vsv-cta .vsv-btn-line{border-color:rgba(255,251,233,.6);color:#FFFBE9}
selector .vsv-cta .vsv-btn-line:hover{background:rgba(255,251,233,.1);border-color:#FFFBE9;color:#FFFBE9}
@media(max-width:1024px){
selector .vsv-split{grid-template-columns:minmax(0,1fr);gap:36px}
selector .vsv-quote{flex-direction:column}
selector .vsv-hero .vsv-img{order:-1}
selector .vsv-hero .vsv-img img{aspect-ratio:16/10}
selector .vsv-sticky{position:static}
selector .vsv-ggrid{grid-template-columns:repeat(3,minmax(0,1fr))}
}
@media(max-width:767px){
selector{padding:16px 0 72px}
selector .vsv-crumbs{font-size:14px}
selector .vsv-title{font-size:38px}
selector .vsv-p{font-size:17px}
selector .vsv-h2,selector .vpa-revs .vpa-h2{font-size:32px}
selector .vsv-sec,selector .vpa-revs{margin-top:72px}
selector .vsv-hero .vsv-img img{aspect-ratio:4/3;border-radius:12px}
selector .vsv-list{grid-template-columns:minmax(0,1fr)}
selector .vsv-btns .vsv-btn{flex:1 1 100%}
selector .vsv-gal-h{flex-direction:column;align-items:flex-start}
selector .vsv-ggrid{grid-template-columns:repeat(2,minmax(0,1fr));grid-auto-rows:170px;gap:10px}
selector .vsv-ggrid figure.w2{grid-column:span 2}
selector .vsv-ggrid figure.h2{grid-row:auto}
selector .vsv-formcard{padding:24px!important}
selector .vsv-faq-l summary{font-size:18px}
selector .vsv-cta{padding:44px 20px}
}
selector .vsv-bul{margin:22px 0 0;padding:0;list-style:none}
selector .vsv-bul li{position:relative;padding:10px 26px 10px 0;border-bottom:1px solid rgba(20,20,20,.1);font-size:17px;line-height:1.5;color:rgba(20,20,20,.85)}
selector .vsv-bul li::before{content:"";position:absolute;right:4px;top:19px;width:8px;height:8px;border-radius:50%;background:var(--e-global-color-vnsgreen,#3A4831)}
selector .vsv-link{display:inline-block;margin-top:22px;font-size:17px;font-weight:500;color:var(--e-global-color-vnsgreen,#3A4831);text-decoration:underline;text-underline-offset:3px}
selector .vsv-img.land img{aspect-ratio:4/3}
selector .vsv-img.port img{aspect-ratio:4/5}
selector .vsv-band{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:0;padding:44px 24px;border-radius:16px;background:var(--e-global-color-vnsgreen,#3A4831);color:#FFFBE9}
selector .vsv-band>div{padding:0 22px;border-inline-start:1px solid rgba(255,251,233,.22)}
selector .vsv-band>div:first-child{border-inline-start:0}
selector .vsv-band svg{display:block;width:30px;height:30px;color:#FFFBE9}
selector .vsv-band h3{margin:16px 0 0;font-family:"Leon","Discovery Fs",system-ui,sans-serif;font-size:22px;font-weight:700;line-height:1.2;color:#FFFBE9}
selector .vsv-band p{margin:8px 0 0;font-size:16px;line-height:1.55;color:rgba(255,251,233,.82)}
@media(max-width:1024px){selector .vsv-band{grid-template-columns:repeat(2,minmax(0,1fr));row-gap:32px}selector .vsv-band>div:nth-child(3){border-inline-start:0}selector .vsv-detail .vsv-img{order:-1}}
@media(max-width:767px){selector .vsv-band{grid-template-columns:minmax(0,1fr);padding:32px 22px}selector .vsv-band>div{padding:0;border:0}selector .vsv-bul li{font-size:16px}}
